import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Portal veröffentlichen","description":"Eine Seite als Portal veröffentlichen, teilen und den Zugriff beschränken.","frontmatter":{"title":"Portal veröffentlichen","description":"Eine Seite als Portal veröffentlichen, teilen und den Zugriff beschränken."},"headers":[],"relativePath":"seiten/portal-veroeffentlichen.md","filePath":"seiten/portal-veroeffentlichen.md","lastUpdated":1786024399000}'),s={name:"seiten/portal-veroeffentlichen.md"};function a(o,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="portal-veroffentlichen" tabindex="-1">Portal veröffentlichen <a class="header-anchor" href="#portal-veroffentlichen" aria-label="Permalink to &quot;Portal veröffentlichen&quot;">​</a></h1><p>Eine Seite ist zunächst nur intern sichtbar. Erst durch einen <strong>Portal-Link</strong> wird sie nach außen erreichbar.</p><h2 id="portal-link-erstellen" tabindex="-1">Portal-Link erstellen <a class="header-anchor" href="#portal-link-erstellen" aria-label="Permalink to &quot;Portal-Link erstellen&quot;">​</a></h2><ol><li>Öffnen Sie die Seite.</li><li>Wählen Sie <strong>Teile diese Seite</strong>.</li><li>Klicken Sie auf <strong>Portal-Link erstellen</strong>.</li></ol><p>Danach stehen zur Verfügung:</p><table tabindex="0"><thead><tr><th>Schaltfläche</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Kopieren</strong></td><td>Link in die Zwischenablage</td></tr><tr><td><strong>Öffnen</strong></td><td>Portal in neuem Tab</td></tr><tr><td><strong>Vorschau</strong></td><td>Ansicht als Smartphone oder Desktop</td></tr><tr><td><strong>QR-Code</strong></td><td>Code zum Herunterladen</td></tr><tr><td><strong>Einschränkungen setzen</strong></td><td>Zugriff beschränken</td></tr><tr><td><strong>Link hinzufügen</strong></td><td>weiterer, eigenständiger Link</td></tr><tr><td><strong>Löschen</strong></td><td>Link entfernen</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Ein Portal-Link ist standardmäßig öffentlich</p><p>Ohne zusätzliche Beschränkung kann <strong>jede Person mit dem Link</strong> das Portal öffnen. Der Link ist nicht erratbar, aber ungeschützt — wird er weitergeleitet, funktioniert er dort weiter.</p><p>Entscheiden Sie <strong>vor</strong> dem Verteilen über <em>Einschränkungen setzen</em>, wer zugreifen darf.</p></div><h2 id="vorschau" tabindex="-1">Vorschau <a class="header-anchor" href="#vorschau" aria-label="Permalink to &quot;Vorschau&quot;">​</a></h2><p>Über <strong>Vorschau</strong> sehen Sie die Seite als <strong>Smartphone</strong> oder <strong>Desktop</strong>.</p><p>Haben Sie noch keinen Portal-Link, fragt ApptiveGrid:</p><blockquote><p><em>Für diese Vorschau als Portal wird ein veröffentlichter Portal-Link benötigt. Möchten Sie ihn jetzt erstellen?</em></p></blockquote><p>Mit <strong>Erstellen und Vorschau anzeigen</strong> legen Sie ihn an. Über <strong>Zurück zur Bearbeitung</strong> kommen Sie in den Editor zurück.</p><div class="tip custom-block"><p class="custom-block-title">Immer beide Breiten prüfen</p><p>Layouts, die am Desktop stimmen, brechen auf dem Smartphone gern um — besonders horizontale Layouts mit mehreren Auswertungsblöcken. Die Vorschau kostet zwei Klicks und erspart Rückmeldungen von Nutzern.</p></div><h2 id="zugriff-beschranken" tabindex="-1">Zugriff beschränken <a class="header-anchor" href="#zugriff-beschranken" aria-label="Permalink to &quot;Zugriff beschränken&quot;">​</a></h2><p><strong>Einschränkungen setzen</strong> öffnet <em>Zugriffsberechtigungen einstellen</em> mit der Frage <em>Legen Sie fest, wer Zugriff hat</em>:</p><table tabindex="0"><thead><tr><th>Option</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Alle</strong></td><td><em>Jede Person mit dem Link kann zugreifen</em></td></tr><tr><td><strong>Mit Anmeldeinformationen</strong></td><td><em>Zugriff nur mit Benutzername und Passwort</em></td></tr></tbody></table><p>Bei der zweiten Option vergeben Sie ein <strong>Benutzername</strong>/<strong>Passwort</strong>-Paar. Das hat nichts mit ApptiveGrid-Konten zu tun — die Empfänger brauchen kein Konto.</p><div class="danger custom-block"><p class="custom-block-title">Zugangsdaten sind nur einmal sichtbar</p><p>Nach dem Speichern erscheint <em>Berechtigungen aktualisiert</em> mit dem Hinweis:</p><blockquote><p><em>Aus Sicherheitsgründen ist es nicht möglich, den Benutzernamen und das Passwort später einzusehen. Sie können diese jedoch jederzeit neu setzen.</em></p></blockquote><p>Notieren Sie beides sofort. Sonst müssen Sie neue Zugangsdaten vergeben und allen Empfängern erneut zuschicken.</p></div><p>Beachten Sie: Für Portale gilt ein <strong>anderes Beschränkungsmodell</strong> als für Formulare. Der Vergleich steht unter <a href="/docs/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a>.</p><h2 id="mehrere-links-auf-dasselbe-portal" tabindex="-1">Mehrere Links auf dasselbe Portal <a class="header-anchor" href="#mehrere-links-auf-dasselbe-portal" aria-label="Permalink to &quot;Mehrere Links auf dasselbe Portal&quot;">​</a></h2><p>Über <strong>Link hinzufügen</strong> legen Sie weitere benannte Links an. Jeder lässt sich einzeln beschränken und entfernen.</p><div class="tip custom-block"><p class="custom-block-title">Zugänge getrennt halten</p><p>Ein Link je Empfängerkreis — einer für Kunde A, einer für Kunde B, einer fürs Intranet. Läuft eine Zusammenarbeit aus, entfernen Sie nur diesen Link. Alle anderen bleiben gültig, und niemand braucht ein neues Passwort.</p><p>Wie viele zusätzliche Links möglich sind, hängt vom Tarif ab.</p></div><p>Alle Links eines Space sind gesammelt unter <a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a> sichtbar.</p><h2 id="qr-code" tabindex="-1">QR-Code <a class="header-anchor" href="#qr-code" aria-label="Permalink to &quot;QR-Code&quot;">​</a></h2><p>Der QR-Code führt direkt zum Portal — für Aushänge, Aufsteller und gedrucktes Material.</p><div class="warning custom-block"><p class="custom-block-title">Gedruckte Codes lassen sich nicht zurückrufen</p><p>Löschen Sie das Portal oder den Link, führt ein gedruckter Code ins Leere. Verwenden Sie für Druckerzeugnisse einen eigenen, benannten Link, den Sie dauerhaft bestehen lassen.</p></div><h2 id="was-besucher-sehen" tabindex="-1">Was Besucher sehen <a class="header-anchor" href="#was-besucher-sehen" aria-label="Permalink to &quot;Was Besucher sehen&quot;">​</a></h2><p>Das veröffentlichte Portal zeigt die Seite im eingestellten <strong>Seitenlayout</strong> — <em>Zentrierte Seite</em>, <em>Volle Breite</em> oder <em>Kartenansicht</em>. Der Hinweis <em>Gilt für die Anzeige im Portal</em> an dieser Einstellung ist wörtlich zu nehmen: Im Editor sieht es anders aus.</p><p>Bearbeitungsfunktionen erscheinen nur, soweit Sie sie freigegeben haben. Bei eingebetteten Grid-Ansichten steuern das die Blockeinstellungen <em>Einträge nur lesbar</em> und <em>Detailansicht nicht öffnen</em>.</p><div class="warning custom-block"><p class="custom-block-title">Vor der Freigabe mit fremden Augen prüfen</p><p>Öffnen Sie den Portal-Link in einem privaten Browserfenster — also ohne Ihre Anmeldung. Nur so sehen Sie, was Außenstehende tatsächlich sehen. Erfahrungsgemäß fällt dabei auf, dass eine eingebettete Ansicht mehr Spalten zeigt als beabsichtigt.</p></div><h2 id="link-entfernen" tabindex="-1">Link entfernen <a class="header-anchor" href="#link-entfernen" aria-label="Permalink to &quot;Link entfernen&quot;">​</a></h2><p>Über <strong>Löschen</strong> im Freigabedialog oder in der <a href="/docs/zusammenarbeit/externe-links">Links-Übersicht</a>.</p><p>Ein entfernter Link funktioniert sofort nicht mehr — auch nicht für Personen, die ihn gespeichert haben. Die Seite selbst bleibt erhalten.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/seiten/portal-einbetten">Portal einbetten</a></li><li><a href="/docs/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li><li><a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a></li></ul>',35)])])}const f=n(s,[["render",a]]);export{g as __pageData,f as default};
